message.content:
{
  "appearance_facts": [
    	{
	"location": "Plot area",
	"fact": "A blue line connects dark blue circular markers, extending from the left side of the chart to the right side."
	},
	{
	"location": "Vertical axis (left)",
	"fact": "The axis labels are arranged in reverse numerical order from top to bottom: 0.0 is at the top, followed by 0.5, 1.0, 1.5, 2.0, and 2.5 at the bottom."
	},
	{
	"location": "Line trajectory",
	"fact": "The line begins at the left (Year 2000.0) at a vertical position aligned with approximately 1.3 on the axis."
	},
	{
	"location": "Line trajectory",
	"fact": "The line descends visually towards the bottom of the chart as it moves to the right (Year 2017.5)."
	},
	{
	"location": "End of period (right side)",
	"fact": "The final marker at Year 2017.5 is positioned lower on the page than the initial marker, aligning with the 2.5 tick mark."
	},
	{
	"location": "Background",
	"fact": "A light purple/blue shaded region fills the area above the line, extending up to the 0.0 axis limit."
	}
  ],
  "printed_facts": [
	{
	"location": "Top center",
	"fact": "Title reads: 'Year vs. Number of doctors per 1,000 inhabitants'"
	},
	{
	"location": "Left axis",
	"fact": "Y-axis label is 'Count' with tick marks labeled 0.0, 0.5, 1.0, 1.5, 2.0, 2.5."
	},
	{
	"location": "Bottom axis",
	"fact": "X-axis label is 'Year' with tick marks labeled 2000.0, 2002.5, 2005.0, 2007.5, 2010.0, 2012.5, 2015.0, 2017.5."
	}
  ],
  "public_definitions": [
	"Physician Capacity Monitoring Triage",
	"Physician capacity relative to population",
	"Dashboard-based follow-up assignment"
  ],
  "uncertain": [
	"The Y-axis is inverted (0.0 at top, 2.5 at bottom), which makes the visual 'descent' of the line correspond to an increase in the numeric value from ~1.3 to ~2.4."
  ]
}
